    "questionEn": "A celestial body of mass $m = 2\\text{ kg}$ orbits under an inverse-square central force with constant angular momentum $L = 40\\text{ J}\\cdot\\text{s}$. Compute the total area $\\Delta A$ swept by its radius vector during a time interval of $\\Delta t = 10\\text{ s}$.",
