    "hintEn": "Circular orbits in central force F(r) = -k/r^n are stable if and only if n < 3.",
    "hintAr": "المدارات الدائرية في مجال قوة F(r) = -k/r^n تكون مستقرة إذا وفقط إذا كان الأس n < 3.",
    "stepByStepSolutionEn": [
      "1. Effective potential derivative gives equilibrium: $\\frac{k}{r_0^n} = \\frac{L^2}{m r_0^3}$.",
      "2. Second derivative condition: $V''_{\\text{eff}}(r_0) = \\frac{L^2}{m r_0^4} (3 - n)$.",
      "3. For stability, we require $V''_{\\text{eff}}(r_0) > 0 \\iff 3 - n > 0 \\iff n < 3$.",
      "4. Here $n = 1$. Therefore, circular orbits are STABLE."
    ],
